<?php
namespace App\Application\Privacy;use App\Application\Audit\AuditWriter;use App\Application\Events\OutboxWriter;use App\Models\{DataSubjectRequest,User};use Illuminate\Support\{Facades\DB,Str};use Illuminate\Validation\ValidationException;
final class DataSubjectRequestService{public function __construct(private AuditWriter$a,private OutboxWriter$o){}public function receive(string$tenant,array$d,User$u):DataSubjectRequest{$hash=hash('sha256',json_encode($d,JSON_THROW_ON_ERROR));if($x=DataSubjectRequest::where(['tenant_id'=>$tenant,'idempotency_key'=>$d['idempotency_key']])->first()){if(!hash_equals($x->payload_hash,$hash))throw ValidationException::withMessages(['idempotency_key'=>__('wave9.idempotency_conflict')]);return$x;}$x=DataSubjectRequest::create([...$d,'tenant_id'=>$tenant,'request_number'=>'DSR-'.strtoupper(Str::random(10)),'status'=>'RECEIVED','payload_hash'=>$hash]);$this->event($x,null,'RECEIVED','REQUEST_RECEIVED',$u);return$x;}public function verify(DataSubjectRequest$x,string$evidence,User$u):DataSubjectRequest{if($x->status!=='RECEIVED')throw ValidationException::withMessages(['status'=>__('wave9.transition_invalid')]);$x->update(['status'=>'VERIFIED','identity_evidence_hash'=>hash('sha256',$evidence),'identity_verified_at'=>now(),'verified_by'=>$u->id]);$this->event($x,'RECEIVED','VERIFIED','IDENTITY_VERIFIED',$u);return$x->refresh();}public function resolve(DataSubjectRequest$x,string$decision,string$notes,User$u):DataSubjectRequest{if(!in_array($x->status,['VERIFIED','IN_PROGRESS'],true)||$x->verified_by===$u->id)throw ValidationException::withMessages(['status'=>__('wave9.maker_checker')]);$to=$decision==='FULFIL'?'COMPLETED':'REJECTED';$x->update(['status'=>$to,'approved_by'=>$u->id,'resolution_notes'=>$notes,'rejection_code'=>$to==='REJECTED'?$decision:null,'fulfilled_at'=>$to==='COMPLETED'?now():null,'completed_at'=>now()]);$this->event($x,$x->getOriginal('status'),$to,$decision,$u);$this->a->record('privacy.request.resolved','data_subject_request',$x->id,['decision'=>$decision]);$this->o->record('privacy.request.resolved','data_subject_request',$x->id,['status'=>$to]);return$x->refresh();}private function event(DataSubjectRequest$x,?string$f,string$t,string$r,User$u):void{DB::table('data_subject_request_events')->insert(['id'=>(string)Str::uuid(),'data_subject_request_id'=>$x->id,'from_status'=>$f,'to_status'=>$t,'reason_code'=>$r,'actor_id'=>$u->id,'metadata'=>'{}','occurred_at'=>now()]);}}
